mapper.update:
/* BmsMobPasmMapper.updateSampleInOutCt : 견품반출 저장 - TB_BMS_IN_PLAN_PKG Update */ UPDATE TB_BMS_IN_PLAN_PKG SET
SAMPLE_IN_CT = 1
SAMPLE_OUT_CT = 1
WHERE PACKING_NO = #{srchNo}

/* BmsMobPasmMapper.updateSampleData : 견품반출 저장 - TB_BMS_SAMPLE Update */ UPDATE TB_BMS_SAMPLE SET
RETURN_DATE = CONVERT(CHAR(10), GETDATE(), 23), RETURN_TIME = CONVERT(CHAR(8), GETDATE(), 8), SEND_IF_YN = 'N',
CARRYOUT_DATE = CONVERT(CHAR(10), GETDATE(), 23), CARRYOUT_TIME = CONVERT(CHAR(8), GETDATE(), 8),
UPDATE_USER_ID = #{updateUserId}, UPDATE_DATE_TIME = GETDATE()
, RETURN_REMARKS = #{returnRemarks}
WHERE BL_NO = #{blNo}

mapper.select:
/* BmsMobPasmMapper.selectSampleTakingOutList : 견품반출 후 입고 박스 번호 조회 */
SELECT P.PACKING_NO, P.SAMPLE_IN_CT, I.BL_NO, S.SAMPLE_NO, S.CARGO_REFERENCE_NO, S.PERMISSION_NO, S.SAMPLE_EMPLOYEE_NAME, S.COMMODITY_ITEM_LOC, S.OD_JOB_NO, ISNULL(tscd.CODE, '') AS RETURN_REMARKS FROM TB_BMS_SAMPLE S INNER JOIN TB_BMS_IN I WITH (NOLOCK) ON S.IN_NO = I.IN_NO INNER JOIN TB_BMS_IN_PLAN_PKG P WITH (NOLOCK) ON I.IN_PLAN_NO = P.IN_PLAN_NO AND I.IN_PLAN_NO > 0 LEFT JOIN TB_SMS_CODE_DETAIL tscd ON tscd.ENT_CODE = #{entCode} AND tscd.GROUP_CODE = 'SAMPLE_RESULT' AND tscd.NAME_${userLanguage} = S.RETURN_REMARKS WHERE P.SAMPLE_OUT_CT = 1 AND P.SAMPLE_IN_CT != 1
AND PACKING_NO = #{srchNo}
ORDER BY S.SAMPLE_NO

/* BmsMobPasmMapper.selectScanLogInfo : 견품반출 스캔 로그 조회 */
SELECT SCAN_NO , BL_NO , SCAN_DATE , SCAN_RESULT , INOUT_STATUS , REGISTER_USER_ID , ISNULL((SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = tbss.REGISTER_USER_ID),'') AS REGISTER_USER_NAME , REGISTER_DATE_TIME FROM TB_BMS_SAMPLE_SCAN tbss WHERE SCAN_DATE BETWEEN CONVERT(VARCHAR(10), ISNULL(#{srchScanDate},''), 120) AND CONVERT(VARCHAR(10), GETDATE(), 120)
AND INOUT_STATUS = #{inOutStatus}
ORDER BY REGISTER_DATE_TIME DESC

mapper.insert:
/* BmsMobPasmMapper."insertSampleScanLog" : 견품반출 스캔 로그 저장 */
INSERT INTO TB_BMS_SAMPLE_SCAN (
	  INOUT_STATUS
	, SCAN_NO
	, BL_NO
	, SCAN_DATE
	, SCAN_RESULT
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
)
VALUES(
	  #{inOutStatus}
	, #{packingNo}
	, #{blNo}
	, CONVERT(VARCHAR(10),GETDATE(),120)
	, #{scanResult}
	, #{registerUserId}
	, GETDATE()
)
